Sure, here's a quick way to do that in HTML and JavaScript:

```html
<!-- The input for the password -->
<input type="password" id="passwordInput" placeholder="Pswrd">

<!-- JS to toggle the visibility -->
<script>
function togglePassword(e) {
  let pwd = document.getElementById('passwordInput');
  let type = pwd.getAttribute('type') === 'password' ? 'text' : 'password';
  pwd.setAttribute('type', type);
  pwd.type = type;
}

document.getElementById('pwdbtn').onclick = () => {
   togglePassword(e);
};
</script>

